/* From Uiverse.io by SujitAdroja - Tags: card, cardgift, cool card, card animation, card hover */
.__UIV_SCOPE__ .columns {
  width: 18em;
  position: relative;
  border-radius: 20px;
  padding: 35px;
  border: 2px solid  black;
  transition: all 0.4s;
}

.__UIV_SCOPE__ .columns:hover {
  box-shadow: 4px 4px 0 1px rgba(0,0,0);
}

.__UIV_SCOPE__ .dots {
  position: absolute;
  right: 15px;
  top: 15px;
}

.__UIV_SCOPE__ .columns .button-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 30px;
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .offer {
  font-size: 17px;
  font-weight: 900;
  border-bottom: 2px solid black;
  cursor: pointer;
  transition: all 0.4s;
}

.__UIV_SCOPE__ .btn {
  padding: 7px 15px;
  border: 1px solid black;
  background-color: orange;
  border-radius: 10px;
  letter-spacing: 1px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.4s;
}

.__UIV_SCOPE__ .columns:hover .btn {
  box-shadow: 2px 2px 0 1px rgba(0,0,0);
}

.__UIV_SCOPE__ .columns:hover .offer {
  color: green;
  border-color: green;
}

.__UIV_SCOPE__ .btn:focus {
  background: transparent;
}

.__UIV_SCOPE__ .secondary-heading {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .card-description {
  font-size: 18px;
  font-weight: 500;
  line-height: 1.2;
}
